<?php
/** Proof — threading (spec "Proof", 2): a reply on our outbound Message-ID lands as the requester's public reply and reopens pending; one by the subject tag lands; a CC's lands as the CC's; Marco's lands as his (and #note as a note); a stranger lands and becomes a CC; a reply to a closed ticket makes a follow-up linked follow_up_of. */
require __DIR__ . '/lib.php';
$W = world();
$marco = as_member(27); $lena = as_member(28);
ensure_mailbox();
$st = json_decode(file_get_contents(need('HD_DEV_STATE') . '/slice7.json'), true);
$t = (int) $st['ticket']; $num = ticket_row($t)['number'];
echo "1. Our reply goes out with a Message-ID; the requester's reply threads on it\n";
act($marco, '/tickets/assign.php', ['ticket' => $t, 'assignee' => 'me']);
[$c, $b] = act($marco, '/tickets/reply.php', ['ticket' => $t, 'body' => 'We will send a technician.', 'then_status' => 'pending']);
ok($c === 200 && ticket_status($t) === 'pending', 'Marco replied and set it pending');
$r = send_batch();
$out = q('SELECT * FROM outbound_email WHERE ticket_id = :t ORDER BY id', ['t' => $t]);
ok($r['sent'] >= 1 && count($out) >= 1 && preg_match('/^<mm-\d+@fake\.malumail>$/', (string) end($out)['provider_message_id']) === 1, 'the batch sent it; the outbound row holds the provider\'s Message-ID');
$ourId = end($out)['provider_message_id'];
put_mail(10, ['from' => 'New Person <new@customer.invalid>', 'subject' => 'Re: [' . $num . '] Printer jams on floor 3', 'in_reply_to' => $ourId, 'references' => [$ourId]], "Great, thanks.\n\nOn Fri, Oct 3, 2026 SMOKE Support wrote:\n> We will send a technician.");
webhook(10);
$row = inbound_row(10);
$m = q('SELECT kind, body_text, author_requester_id, in_reply_to FROM messages WHERE id = :m', ['m' => (int) $row['message_ref_id']])[0];
ok($row['status'] === 'processed' && (int) $row['ticket_id'] === $t && $m['kind'] === 'public_reply' && (int) $m['author_requester_id'] === $st['requester'] && $m['body_text'] === 'Great, thanks.' && $m['in_reply_to'] === $ourId, 'threaded by In-Reply-To: the requester\'s public reply, the quoted part stripped');
ok(ticket_status($t) === 'open' && ticket_row($t)['last_requester_reply_at'] !== null, 'and the pending ticket reopened');
ok(count(outbox_rows($t)) >= 1 && count(array_filter(outbox_rows($t), fn ($o) => $o['kind'] === 'replied' && (int) $o['member_id'] === 27)) >= 1, 'Marco (the assignee) is told');
echo "2. By the subject tag, by a CC, by Marco, by a stranger\n";
put_mail(11, ['from' => 'New Person <new@customer.invalid>', 'subject' => '[' . $num . '] one more thing'], 'Also the scanner.');
webhook(11);
ok((int) inbound_row(11)['ticket_id'] === $t, 'only [' . $num . '] in the subject: lands too');
act($marco, '/tickets/cc.php', ['ticket' => $t, 'cc' => 'boss@customer.invalid']);
put_mail(12, ['from' => 'Boss <boss@customer.invalid>', 'subject' => 'Re: [' . $num . '] Printer jams on floor 3'], 'Please hurry.');
webhook(12);
$m = q('SELECT author_requester_id, kind FROM messages WHERE id = :m', ['m' => (int) inbound_row(12)['message_ref_id']])[0];
ok((int) inbound_row(12)['ticket_id'] === $t && (int) $m['author_requester_id'] === (int) one("SELECT id FROM requesters WHERE primary_email = 'boss@customer.invalid'") && $m['kind'] === 'public_reply', 'the CC\'s mail lands as the CC\'s public reply');
$marcoEmail = (string) one('SELECT email FROM members WHERE id = 27');
put_mail(13, ['from' => 'SMOKE Marco <' . $marcoEmail . '>', 'subject' => 'Re: [' . $num . '] Printer jams on floor 3'], "The technician comes Monday.\n\n-----Original Message-----\nFrom: New\nSent: yesterday\nblah");
webhook(13);
$m = q('SELECT author_member_id, kind, body_text FROM messages WHERE id = :m', ['m' => (int) inbound_row(13)['message_ref_id']])[0];
ok((int) $m['author_member_id'] === 27 && $m['kind'] === 'public_reply' && $m['body_text'] === 'The technician comes Monday.', 'Marco\'s mail lands as HIS public reply (the original message stripped)');
ok(ticket_row($t)['last_agent_reply_at'] !== null && count(array_filter(outbox_rows($t), fn ($o) => $o['kind'] === 'replied' && $o['requester_id'] !== null)) >= 1, 'it counts as an agent reply and the requester is told');
put_mail(14, ['from' => 'SMOKE Marco <' . $marcoEmail . '>', 'subject' => 'Re: [' . $num . '] Printer jams on floor 3'], "#note Jo is a VIP, be gentle.");
webhook(14);
$m = q('SELECT author_member_id, kind, body_text FROM messages WHERE id = :m', ['m' => (int) inbound_row(14)['message_ref_id']])[0];
ok($m['kind'] === 'internal_note' && $m['body_text'] === 'Jo is a VIP, be gentle.' && (int) $m['author_member_id'] === 27, '#note first: an internal note by Marco');
$since = last_activity_id();
put_mail(15, ['from' => 'Stranger <stranger@elsewhere.invalid>', 'subject' => 'Re: [' . $num . '] Printer jams on floor 3'], 'I was forwarded this; the printer is a model X.');
webhook(15);
$sid = (int) one("SELECT id FROM requesters WHERE primary_email = 'stranger@elsewhere.invalid'");
ok((int) inbound_row(15)['ticket_id'] === $t && (int) one("SELECT count(*) FROM ticket_followers WHERE ticket_id = :t AND kind = 'cc' AND requester_id = :r", ['t' => $t, 'r' => $sid]) === 1 && count(activity('ticket.cc_add', $since)) === 1, 'a stranger lands and becomes a CC');
echo "3. A reply to a closed ticket\n";
act($marco, '/tickets/transition.php', ['ticket' => $t, 'status' => 'solved', 'resolution_code' => 'resolved']);
act($lena, '/tickets/close.php', ['ticket' => $t, 'resolution_code' => 'resolved']);
$since = last_activity_id();
put_mail(16, ['from' => 'New Person <new@customer.invalid>', 'subject' => 'Re: [' . $num . '] Printer jams on floor 3', 'in_reply_to' => '<mail-1@customer.invalid>'], 'It is jamming again!');
webhook(16);
$row = inbound_row(16);
$new = (int) $row['ticket_id'];
ok($row['status'] === 'processed' && $new !== $t && $new > 0, 'a follow-up ticket was made');
$nr = ticket_row($new);
ok((int) $nr['requester_id'] === $st['requester'] && $nr['channel'] === 'email' && $nr['subject'] === 'Printer jams on floor 3' && (int) one("SELECT count(*) FROM ticket_links WHERE from_ticket_id = :n AND to_ticket_id = :t AND kind = 'follow_up_of'", ['n' => $new, 't' => $t]) === 1, 'same requester, the subject kept, linked follow_up_of');
ok(count(array_filter(activity('ticket.create', $since), fn ($r) => (int) $r['ticket_id'] === $new && json_decode($r['after'], true)['channel'] === 'email')) === 1 && count(array_filter(activity('ticket.link', $since), fn ($r) => (int) $r['ticket_id'] === $new)) === 1, 'ticket.create (channel email) and ticket.link logged');
ok(count(outbox($new, 'created')) === 1 && str_contains(outbox($new, 'created')[0]['body'], $nr['number']), 'the requester is told of the new number');
finish();
